var __pageData = JSON.parse("{\"title\":\"Roadmap\",\"description\":\"OpenPencil product roadmap and Figma compatibility tracking.\",\"frontmatter\":{\"title\":\"Roadmap\",\"description\":\"OpenPencil product roadmap and Figma compatibility tracking.\",\"head\":[[\"link\",{\"rel\":\"canonical\",\"href\":\"https://openpencil.dev/development/roadmap\"}],[\"meta\",{\"property\":\"og:url\",\"content\":\"https://openpencil.dev/development/roadmap\"}],[\"meta\",{\"property\":\"og:locale\",\"content\":\"en_US\"}],[\"link\",{\"rel\":\"alternate\",\"hreflang\":\"en\",\"href\":\"https://openpencil.dev/development/roadmap\"}],[\"link\",{\"rel\":\"alternate\",\"hreflang\":\"x-default\",\"href\":\"https://openpencil.dev/development/roadmap\"}],[\"meta\",{\"property\":\"og:title\",\"content\":\"Roadmap — OpenPencil\"}],[\"meta\",{\"name\":\"twitter:title\",\"content\":\"Roadmap — OpenPencil\"}],[\"meta\",{\"property\":\"og:description\",\"content\":\"OpenPencil product roadmap and Figma compatibility tracking.\"}],[\"meta\",{\"name\":\"twitter:description\",\"content\":\"OpenPencil product roadmap and Figma compatibility tracking.\"}],[\"meta\",{\"name\":\"description\",\"content\":\"OpenPencil product roadmap and Figma compatibility tracking.\"}]]},\"headers\":[],\"relativePath\":\"development/roadmap.md\",\"filePath\":\"development/roadmap.md\",\"lastUpdated\":1791491620000}");
